/**
 * @ignore
 * @method
 * @name sxbet#hashEip712Digest
 * @description hashes an EIP-712 encoded payload (domainSeparator‖structHash, prefixed with 0x1901 by ccxt.EthEncodeStructuredData) down to the final 32-byte digest to sign, used by sx.bet's taker-fill and cancel signatures
 * @param {Uint8Array} encoded the output of this.ethEncodeStructuredData (domain, types, message)
 * @returns {string} the 32-byte digest to ecdsa-sign, in '0x'-prefixed hex form
 */
func (this *Sxbet) HashEip712Digest(encoded any) any {
	return ccxt.Add("0x", this.Hash(encoded, ccxt.Keccak, "hex"))
}

/**
 * @ignore
 * @method
 * @name sxbet#signDigest
 * @description ecdsa-signs a 32-byte digest and assembles the r‖s‖v hex signature sx.bet expects
 * @param {string} digest the '0x'-prefixed 32-byte digest to sign
 * @param {string} privateKey the signer's private key
 * @returns {string} a '0x'-prefixed 65-byte hex signature (r‖s‖v)
 */
func (this *Sxbet) SignDigest(digest any, privateKey any) any {
	var signature map[string]any = ccxt.Ecdsa(ccxt.Slice(digest, ccxt.OpNeg(64), nil), ccxt.Slice(privateKey, ccxt.OpNeg(64), nil), ccxt.Secp256k1, nil)
	// assign to bare locals before padStart — the php transpiler's str_pad regex only
	// matches a simple identifier, an expression form leaks a raw padStart() call
	var rRaw *string = ccxt.SafeStringPtr(signature["r"])
	var sRaw *string = ccxt.SafeStringPtr(signature["s"])
	var r string = ccxt.PadStart(rRaw, 64, "0")
	var s string = ccxt.PadStart(sRaw, 64, "0")
	var v string = this.IntToBase16(this.Sum(27, signature["v"]))
	return "0x" + r + s + v
}

/**
 * @ignore
 * @method
 * @name sxbet#fetchErc20Name
 * @description reads an ERC20 token's name() via eth_call (needed for the Permit EIP-712 domain — must match the token's real on-chain name or the signature fails verification)
 * @param {string} rpcUrl the RPC endpoint to call
 * @param {string} tokenAddress the token contract address
 * @returns {string} the token's on-chain name
 */
func (this *Sxbet) FetchErc20NameAsync(rpcUrl any, tokenAddress any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchErc20NameBody(ch, rpcUrl, tokenAddress)
	return ch
}
func (this *Sxbet) fetchErc20NameBody(ch chan any, rpcUrl any, tokenAddress any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var nameCallData string = "0x06fdde03" // name()

	result := (<-this.EthRpcAsync(rpcUrl, "eth_call", []any{map[string]any{
		"to":   tokenAddress,
		"data": nameCallData,
	}, "latest"}))
	ccxt.PanicOnError(result)
	var hex string = this.Remove0xPrefix(result)
	// dynamic ABI string return: [32-byte offset][32-byte length][utf8 bytes, right-padded]
	var lengthHex string = hex[64:min(128, len(hex))]
	var length any = this.HexToInt(lengthHex)
	var dataEnd any = this.Sum(128, ccxt.Multiply(length, 2))
	var dataHex string = ccxt.Slice(hex, 128, dataEnd)

	ch <- this.Decode(this.Base16ToBinary(dataHex))
	return nil
}

/**
 * @ignore
 * @method
 * @name sxbet#hexToInt
 * @description parses a hex string (no '0x' prefix) into an integer — plain digit-by-digit, since JS's parseInt (hex, 16) two-argument form has no portable equivalent across languages/transpilers. Only used for small values (byte lengths, permit nonces), safe well within the float-precision range
 * @param {string} hex the hex string, no '0x' prefix
 * @returns {int} the parsed integer
 */
func (this *Sxbet) HexToInt(hex any) any {
	var digits string = "0123456789abcdef"
	var lowerHex string = ccxt.ToLower(hex)
	var hexLength int = len(lowerHex)
	var result any = 0
	for i := 0; i < hexLength; i++ {
		var ch any = ccxt.GetValue(lowerHex, i)
		var digitValue int = ccxt.GetIndexOf(digits, ch)
		result = ccxt.Add((ccxt.Multiply(result, 16)), digitValue)
	}
	return result
}

