/**
 * @ignore
 * @method
 * @name sxbet#parseSxbetV3PublicTrade
 * @description parses one recent_trades_v3 publication (public TradeV3 shape) into a unified trade
 * @param {object} trade the raw public trade row
 * @returns {object} a [prediction trade structure](https://docs.ccxt.com/#/?id=prediction-trade-structure)
 */
func (this *Sxbet) ParseSxbetV3PublicTrade(trade any) any {
	var marketHash *string = this.SafeString(trade, "marketHash", "")
	var isBettingOutcomeOne *bool = this.SafeBool(trade, "isBettingOutcomeOne", true)
	var outcomeId any = nil
	if isBettingOutcomeOne != nil && *isBettingOutcomeOne {
		outcomeId = marketHash
	} else {
		outcomeId = (*marketHash + "-2")
	}
	var outcomeObj map[string]any = this.SafeOutcome(outcomeId)
	var oneDenom string = "100000000000000000000"
	var usdcDecimals string = "1000000"
	var odds *string = this.SafeString(trade, "weightedAverageOdds")
	var price *float64 = func() *float64 {
		if odds != nil {
			return ccxt.Float64PtrTyped(this.ParseNumber(ccxt.Precise.StringDiv(odds, oneDenom)))
		}
		return nil
	}()
	var stake *string = this.SafeString(trade, "totalStake", "0")
	var amount *float64 = ccxt.Float64PtrTyped(this.ParseNumber(ccxt.Precise.StringDiv(stake, usdcDecimals, 6)))
	var timestamp *int64 = this.Parse8601(this.SafeString(trade, "betTime"))
	return this.SafePredictionTrade(map[string]any{
		"id":           this.SafeString(trade, "tradeId"),
		"info":         trade,
		"timestamp":    timestamp,
		"datetime":     this.Iso8601(timestamp),
		"outcome":      this.SafeString(outcomeObj, "outcome"),
		"outcomeId":    this.SafeString(outcomeObj, "outcomeId", outcomeId),
		"label":        this.SafeString(outcomeObj, "label"),
		"market":       this.SafeString(outcomeObj, "market"),
		"order":        nil,
		"type":         nil,
		"side":         "buy",
		"takerOrMaker": nil,
		"price":        price,
		"amount":       amount,
		"cost":         amount,
		"fee":          nil,
	})
}
func (this *Sxbet) HandleTrades(client any, rows any) {
	//
	//     { "trade": { "tradeId": "0xac6b...", "marketHash": "0x1fec...", "isBettingOutcomeOne": true,
	//                  "totalStake": "1000000", "weightedAverageOdds": "40000000000000000000",
	//                  "betTime": "2026-07-31T18:22:41.000Z", ... } }
	//
	var rowsLength int = ccxt.GetArrayLength(rows)
	for i := 0; i < rowsLength; i++ {
		var row any = this.SafeDict(ccxt.GetValue(rows, i), "trade", ccxt.GetValue(rows, i))
		var trade any = this.ParseSxbetV3PublicTrade(row)
		var sym *string = this.SafeString(trade, "outcome")
		if sym == nil {
			continue
		}
		if ccxt.IsEqual(this.Trades, nil) {
			this.Trades = this.CreateSafeDictionary()
		}
		if ccxt.IsEqual(this.SafeValue(this.Trades, sym), nil) {
			var tradesLimit *int64 = this.SafeInteger(this.Options, "tradesLimit", 1000)
			ccxt.AddElementToObject(this.Trades, sym, ccxt.NewArrayCache(tradesLimit))
		}
		var stored any = ccxt.GetValue(this.Trades, sym)
		stored.(ccxt.Appender).Append(trade)
		client.(ccxt.ClientInterface).Resolve(stored, "trades::"+*sym)
	}
}

/**
 * @method
 * @name sxbet#watchMyTrades
 * @description streams the authenticated wallet's fills over its per-account v3 channel
 * @see https://docs.sx.bet/api-reference/channel-fills-v3
 * @param {string} [outcome] unified outcome or outcome token id to narrow the stream down to
 * @param {int} [since] timestamp in ms of the earliest trade to return
 * @param {int} [limit] the maximum number of trades to return
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object[]} a list of [prediction trade structures](https://docs.ccxt.com/#/?id=prediction-trade-structure)
 */
func (this *Sxbet) WatchMyTradesAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.watchMyTradesBody(ch, optionalArgs...)
	return ch
}
func (this *Sxbet) watchMyTradesBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var outcome *string = ccxt.GetArgStringPtr(optionalArgs, 0, nil)
	_ = outcome
	var since *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if ccxt.IsEqual(this.WalletAddress, nil) {
		panic(ccxt.ArgumentsRequired(this.Id + " watchMyTrades() requires a walletAddress"))
	}
	var messageHash any = "myTrades"
	if outcome != nil {

		ccxt.PanicOnError((<-this.LoadOutcomeAsync(outcome)))
		var outcomeObj map[string]any = this.Outcome(outcome)
		var sym *string = this.SafeString(outcomeObj, "outcome")
		messageHash = ccxt.Add("myTrades::", sym)
	}
	var channel *string = ccxt.SafeStringPtr(ccxt.Add("account:fills_v3_#", this.WalletAddress))

	var trades ccxt.ArrayCacheInterface = ccxt.AsArrayCache(ccxt.PanicOnError((<-this.SubscribeSxbetChannelAsync(messageHash, channel))))

	ch <- this.FilterBySinceLimit(trades, since, limit, "timestamp", true)
	return nil
}
func (this *Sxbet) HandleMyTrade(client any, rows any) {
	//
	//     FillV3 rows - identical to GET /fills-v3
	//
	var rowsLength int = ccxt.GetArrayLength(rows)
	for i := 0; i < rowsLength; i++ {
		var row any = this.SafeDict(ccxt.GetValue(rows, i), "fill", ccxt.GetValue(rows, i))
		var trade any = this.ParseSxbetV3Fill(row)
		var sym *string = this.SafeString(trade, "outcome")
		if sym == nil {
			continue
		}
		if ccxt.IsEqual(this.MyTrades, nil) {
			var myTradesLimit *int64 = this.SafeInteger(this.Options, "myTradesLimit", 1000)
			this.MyTrades = ccxt.NewArrayCacheByOutcomeById(myTradesLimit)
		}
		var stored any = this.MyTrades
		stored.(ccxt.Appender).Append(trade)
		client.(ccxt.ClientInterface).Resolve(stored, "myTrades")
		client.(ccxt.ClientInterface).Resolve(stored, "myTrades::"+*sym)
	}
}

